def resid_model(p, extra):
    w,ph=p
    B=np.c_[np.sqrt(P),P,P*np.sin(w*t+ph)]+0
    if extra is not None: B=np.c_[B,extra]
    c=np.linalg.lstsq(B,dP_dt,rcond=None)[0]
    return dP_dt-B@c
